    //Driver Code Starts
#include <iostream>
#include <vector>
#include <climits>
using namespace std;

//Driver Code Ends

int minCost = INT_MAX;

// directions: up, down, right, left
int dirArr[4][2] = {{-1,0},{1,0},{0,1},{0,-1}};

// checks if the next cell is within bounds and not visited
bool isSafe(int x, int y, int d[2], vector<vector<int>>& mat) {
    int n = mat.size();
    int m = mat[0].size();

    if (x + d[0] >= 0 && x + d[0] < n &&
        y + d[1] >= 0 && y + d[1] < m &&
        mat[x + d[0]][y + d[1]] != -1)
        return true;

    return false;
}

// explores all possible paths using backtracking and updates minimum cost
void findMinCost(int i, int j, int maxDiff, vector<vector<int>>& mat) {
    int n = mat.size(); 
    int m = mat[0].size();

    // reached destination → update global minimum
    if (i == n - 1 && j == m - 1) {
        minCost = min(minCost, maxDiff);
        return;
    }

    int curr = mat[i][j];

    // mark current cell as visited
    mat[i][j] = -1;

    for (auto& d : dirArr) {

        // move only if next cell is valid
        if (isSafe(i, j, d, mat)) {

            // continue path with updated maximum difference
            findMinCost(i + d[0], j + d[1],
                max(maxDiff, abs(mat[i + d[0]][j + d[1]] - curr)), mat);
        }
    }

    // restore cell value for other paths
    mat[i][j] = curr;
}

// initiates backtracking and
// returns minimum possible path cost
int minCostPath(vector<vector<int>>& mat) {
    minCost = INT_MAX;
    findMinCost(0, 0, 0, mat);
    return minCost;
}

//Driver Code Starts

int main() {
    vector<vector<int>> mat = {
        {7, 2, 6, 5},
        {3, 1, 10, 8}
    };

    cout << minCostPath(mat);
}

