    //Driver Code Starts
#include <iostream>
#include <vector>
#include <climits>
using namespace std;

//Driver Code Ends

// directions: up, down, right, left
int dirArr[4][2] = {{-1,0},{1,0},{0,1},{0,-1}};

// DFS to check if we can reach destination
// with max allowed difference = limit
bool dfs(int x, int y, int limit, vector<vector<int>>& mat, 
                                    vector<vector<int>>& vis) {
    int n = mat.size();
    int m = mat[0].size();

    // reached destination
    if (x == n - 1 && y == m - 1)
        return true;

    vis[x][y] = 1;

    for (auto& d : dirArr) {
        int nx = x + d[0];
        int ny = y + d[1];

        // valid move inside grid and not visited
        if (nx >= 0 && nx < n && ny >= 0 && ny < m && !vis[nx][ny]) {

            // move only if difference is within allowed limit
            if (abs(mat[nx][ny] - mat[x][y]) <= limit) {
                if (dfs(nx, ny, limit, mat, vis))
                    return true;
            }
        }
    }

    return false;
}

// checks if path exists for given maximum allowed difference
bool canReach(int limit, vector<vector<int>>& mat) {
    int n = mat.size();
    int m = mat[0].size();
    vector<vector<int>> vis(n, vector<int>(m, 0));
    return dfs(0, 0, limit, mat, vis);
}

// binary search on minimum possible maximum difference
int minCostPath(vector<vector<int>>& mat) {
    int low = 0, high = 0;

    int n = mat.size();
    int m = mat[0].size();

    // compute upper bound of differences
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (i + 1 < n) high = max(high, abs(mat[i+1][j] - mat[i][j]));
            if (j + 1 < m) high = max(high, abs(mat[i][j+1] - mat[i][j]));
        }
    }

    int ans = high;

    // binary search to find smallest feasible limit
    while (low <= high) {
        int mid = (low + high) / 2;

        if (canReach(mid, mat)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    return ans;
}

