// Custom min-heap
class MinHeap {
    private List<Cell> heap = new List<Cell>();

    private void Swap(int i,int j){
        var tmp = heap[i];
        heap[i] = heap[j];
        heap[j] = tmp;
    }

    public void Push(Cell c){
        heap.Add(c);
        int i = heap.Count-1;
        while(i>0){
            int parent=(i-1)/2;
            if(heap[i].CompareTo(heap[parent])>=0) break;
            Swap(i,parent);
            i=parent;
        }
    }

    public Cell Pop(){
        var top = heap[0];
        Swap(0,heap.Count-1);
        heap.RemoveAt(heap.Count-1);
        int i=0;
        while(true){
            int left=2*i+1, right=2*i+2, smallest=i;
            if(left<heap.Count && heap[left].CompareTo(heap[smallest])<0) smallest=left;
            if(right<heap.Count && heap[right].CompareTo(heap[smallest])<0) smallest=right;
            if(smallest==i) break;
            Swap(i,smallest);
            i=smallest;
        }
        return top;
    }

    public int Count() => heap.Count;
}

