class PriorityQueue {
    constructor() {
        this.heap = [];
    }

    push(cell) {
        this.heap.push(cell);
        this._heapifyUp();
    }

    pop() {
        if(this.size() === 0) return null;
        const top = this.heap[0];
        const last = this.heap.pop();
        if(this.size() > 0) {
            this.heap[0] = last;
            this._heapifyDown();
        }
        return top;
    }

    size() {
        return this.heap.length;
    }

    _heapifyUp() {
        let idx = this.heap.length - 1;
        while(idx > 0) {
            let parent = Math.floor((idx - 1) / 2);
            if(this.heap[idx].cost >= this.heap[parent].cost) break;
            [this.heap[idx], this.heap[parent]] = [this.heap[parent], this.heap[idx]];
            idx = parent;
        }
    }

    _heapifyDown() {
        let idx = 0;
        const n = this.heap.length;
        while(true) {
            let left = 2*idx + 1, right = 2*idx + 2;
            let smallest = idx;

            if(left < n && this.heap[left].cost < this.heap[smallest].cost) smallest = left;
            if(right < n && this.heap[right].cost < this.heap[smallest].cost) smallest = right;
            if(smallest === idx) break;

            [this.heap[idx], this.heap[smallest]] = [this.heap[smallest], this.heap[idx]];
            idx = smallest;
        }
    }
}

